CREATE TABLE "agency_legacy_negotiations" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "agency_legacy_negotiations_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"agency_id" bigint NOT NULL,
	"company" text NOT NULL,
	"lob" text NOT NULL,
	"agent_rate" numeric(5, 2) NOT NULL,
	"admin_fee" numeric(10, 2),
	"detail" text NOT NULL,
	"valid_from" date DEFAULT now() NOT NULL,
	"valid_to" date,
	CONSTRAINT "agency_legacy_rate" CHECK ("agency_legacy_negotiations"."agent_rate" >= 0 AND "agency_legacy_negotiations"."agent_rate" <= 100),
	CONSTRAINT "agency_legacy_fee" CHECK ("agency_legacy_negotiations"."admin_fee" IS NULL OR "agency_legacy_negotiations"."admin_fee" >= 0)
);
